<?php foreach(DB::select("SHOW COLUMNS FROM pages") as $c) echo $c->Field." ".$c->Type.PHP_EOL; echo "----sites\n"; foreach([2,62,460,477,478,504,507,508,509,514,515,516,903,919,996] as $id){ $w=DB::table("websites")->where("id",$id)->first(); $n=DB::table("pages")->where("website_id",$id)->count(); $types=[]; foreach(DB::table("pages")->where("website_id",$id)->get() as $p){ $s=json_decode((string)($p->sections_json??$p->content??"[]"),true); if(is_array($s)) foreach($s as $sec){ if(is_array($sec)&&isset($sec["type"])) $types[$sec["type"]]=1; } } $tpl=json_decode((string)$w->settings_json,true)["template"]??""; echo "$id ".$w->subdomain." pages=$n tpl=".$tpl." types=".implode(",",array_keys($types)).PHP_EOL; }
